import {renderQuestTrail} from './atlas-labs.js';
import {renderLessonDemo} from './renewal-labs.js';
import {chapters,roadmap,allQuestions} from './content.js';
import {art} from './art.js';
import {newLabState,labAnswer,renderPlayground} from './playgrounds.js';
const CUSTOM_TYPES=new Set(['editor','postbox','rail','architect','beacon','album','spotlight','pack','portrait','mirror','director','camera','worlds','conductor','passive','treasure','capsule','relative','chain','balance','museum','launch','freeze','compress']);
const questionSentence=q=>q.type==='editor'?q.original:q.type==='album'?q.frame.replace('{form}','___'):['postbox','rail','architect','beacon','album','spotlight'].includes(q.type)?q.sentence:['museum','launch','freeze','compress'].includes(q.type)?({museum:'Collect the activity.',launch:'Choose the participant and the form.',freeze:'Match the scene and the form.',compress:q.full}[q.type]):['relative','chain','balance'].includes(q.type)?({relative:'Connect the clue to its anchor.',chain:'Connect the events.',balance:'Build the bridge and compare.'}[q.type]):['passive','treasure','capsule'].includes(q.type)?({passive:q.active,treasure:'Place the star and choose the phrase.',capsule:'Ship the whole clause.'}[q.type]):['camera','worlds','conductor'].includes(q.type)?(q.type==='camera'?'Set the time camera.':q.type==='worlds'?'Build the story bridge.':q.frame):q.type==='mirror'?q.subject+' ___ '+q.tail+'.':q.type==='pack'?'Pack the picnic bag.':q.type==='director'?'Build the scene.':q.sentence;
const chapterTag=c=>c.kind==='integrated'?'跨章综合':c.kind==='extension'?'拓展 · '+(c.extensionLabel||'BE'):c.id==='t1'?'时态样板':'CHAPTER '+c.number+(c.refined?' · 本轮精修':'');
const gameTitle=(q,c)=>({editor:'先选候选稿，再核对保留的意思',postbox:'找到词卡，亲手投递职业',rail:'连接整组词块与角色',architect:'建一座骨架房，再接关系',beacon:'给 be 接上本次工作灯',album:'翻相册，走适应坡，找工具用途',spotlight:'让 it 找到对应的舞台',pack:'把野餐装进背包',portrait:'哪位朋友符合所有线索？',mirror:'给 be 找到正确搭档',director:'这个故事，由你来拍',camera:'把摄影机放到故事的时间',worlds:'现实不变，搭一座愿望桥',conductor:'谁握指挥棒，动词就听谁',passive:'换一个主角，保留同一件事',treasure:'摆好星星，再接上关系短语',capsule:'装好整个想法，送到合适泊位',relative:'把线索接回它描述的对象',chain:'选对机关，把故事连起来',balance:'同层搭桥，同一维度比较',museum:'把活动收藏到合适展架',launch:'找到参与者，接好任务路径',freeze:'对准对象，定格动作关系',compress:'缩短句子，再恢复原来的意思'}[q.type]||(q.type==='build'?'把句子搭起来':q.type==='role'?'给句子找角色':q.type==='time'?'这句话，属于哪个镜头？':c.id==='c1'?'这封词语信，送去哪里？':c.id==='c3'?'找到这句话的骨架':'给场景找合适的表达'));
function updateLab(){const q=session.questions[session.index],old=document.activeElement,data=old?.dataset?{...old.dataset}:null;const host=$('#playground-host');if(host)host.outerHTML=renderPlayground(q,session,art,esc);if(data){const next=[...document.querySelectorAll('#playground-host button')].find(b=>!b.disabled&&Object.keys(data).every(k=>b.dataset[k]===data[k]));next?.focus({preventScroll:true});}}
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='grammar-island-v1';
const initial=()=>({version:1,done:[],solved:{},wrong:[],settings:{rate:.8,motion:true,auto:false},last:'c1'});
let saveAvailable=true,state=initial();
function sanitize(v){const fresh=initial(),ids=new Set(allQuestions.map(q=>q.id)),ms=new Set(chapters.flatMap(c=>c.missions.map(m=>m.id)));if(!v||v.version!==1)throw Error('文件版本不受支持');fresh.done=[...new Set((Array.isArray(v.done)?v.done:[]).filter(x=>ms.has(x)))];fresh.wrong=[...new Set((Array.isArray(v.wrong)?v.wrong:[]).filter(x=>ids.has(x)))];for(const [k,value] of Object.entries(v.solved||{}))if(ids.has(k)&&value&&typeof value.independent==='boolean')fresh.solved[k]={independent:value.independent};fresh.last=chapters.some(c=>c.id===v.last)?v.last:'c1';fresh.settings={rate:[.65,.8,1].includes(Number(v.settings?.rate))?Number(v.settings.rate):.8,motion:v.settings?.motion!==false,auto:v.settings?.auto===true};return fresh;}
try{const raw=localStorage.getItem(KEY);if(raw)state=sanitize(JSON.parse(raw));}catch{saveAvailable=false;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));saveAvailable=true;}catch{saveAvailable=false;toast('浏览器无法保存进度，请导出备份。');}document.body.classList.toggle('still',!state.settings.motion);updateNav();}
document.body.classList.toggle('still',!state.settings.motion);
let view='home',currentChapter=null,lessonIndex=0,session=null,voices=[],speechToken=0;
const missionById=id=>chapters.flatMap(c=>c.missions).find(m=>m.id===id),chapterById=id=>chapters.find(c=>c.id===id);
const qById=id=>allQuestions.find(q=>q.id===id);
const progress=c=>c.missions.filter(m=>state.done.includes(m.id)).length;
const solvedCount=()=>Object.keys(state.solved).length;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function go(hash){if(location.hash==='#'+hash)route();else location.hash=hash;}
function updateNav(){const count=$('#review-count');if(count)count.textContent=state.wrong.length;document.querySelectorAll('[data-nav]').forEach(b=>{const active=b.dataset.nav===(view==='plan'?'plan':view==='review'?'review':'home');b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
function render(html,reset=true){$('#main').innerHTML=html;updateNav();if(reset)window.scrollTo({top:0,behavior:'instant'});const h=$('#main h1');if(h&&reset){h.tabIndex=-1;h.focus({preventScroll:true});}}
const label=(text)=>`<p class="eyebrow">${text}</p>`;
const btn=(text,action,extra='',cl='primary')=>`<button class="${cl}" data-action="${action}" ${extra}>${text}</button>`;
function completePercent(){return Math.round(state.done.length/chapters.reduce((s,c)=>s+c.missions.length,0)*100);}
function nextChapter(){return chapters.find(c=>progress(c)<c.missions.length)||chapters[0];}
function home(){view='home';const next=nextChapter();render(`<section class="hero"><div class="hero-copy">${label('HELLO, LITTLE EXPLORER')}<div class="pill"><span class="dot"></span> 从零开始，也能慢慢说出好句子</div><h1>把英语语法，<br>变成一场<span class="underline">小冒险。</span></h1><p class="intro">和小狐狸阿栗一起，给词语找工作、让句子开火车。<br class="desktop-only">不用死记硬背，动手玩一玩，语法就有了画面。</p><div class="hero-actions">${btn(state.done.length?'继续我的探险 <span>↗</span>':'出发，认识词语 <span>↗</span>','chapter',`data-id="${next.id}"`)}${btn('参加开园庆典 →','chapter','data-id="quest"','text-button')}${btn('看看全书地图 ↓','scroll-map','','text-button')}</div><div class="hero-facts"><span>◉ 图解小故事</span><span>♫ 中英听读</span><span>✦ 没有倒计时</span></div></div><div class="hero-art">${art('island')}<div class="speech-bubble">Hi! 我是阿栗。<br><strong>一起发现语法的秘密吧！</strong><span>✧</span></div><span class="art-caption">YOUR VERY FIRST GRAMMAR ADVENTURE</span></div></section>
<section class="journey-strip" aria-label="当前学习进度"><div class="journey-icon">✦</div><div><strong>${state.done.length?'你的小岛正在一点点长大':'每一次好奇，都值得一颗星星'}</strong><p>现有 ${chapters.length} 个可玩区域 · ${chapters.reduce((s,c)=>s+c.missions.length,0)} 个任务 · ${allQuestions.length} 个互动挑战</p></div><div class="strip-progress"><span>已开放内容的学习进度 <b>${completePercent()}%</b></span><div class="progress-track"><i style="width:${completePercent()}%"></i></div></div><span class="seed-count">✧ ${solvedCount()} <small>已学挑战</small></span></section>
<section class="islands" id="islands"><div class="section-heading"><div>${label('YOUR LEARNING TRAIL')}<h2>今天，想去哪座小岛？</h2></div><p>循序渐进地走，也可以先去感兴趣的地方。</p></div><div class="island-grid">${chapters.map(c=>`<button class="island-card ${c.theme}" data-action="chapter" data-id="${c.id}"><div class="card-art">${art(c.scene)}<span class="chapter-tag">${chapterTag(c)}</span><span class="card-arrow">↗</span></div><div class="card-copy"><p class="card-mechanic">${c.mechanic}</p><h3>${c.title}</h3><p>${c.subtitle}</p><div class="card-bottom"><span>${progress(c)} / ${c.missions.length} 个任务完成</span><span>${progress(c)===c.missions.length?'✦ 已探索':'开始探索 →'}</span></div><div class="progress-track"><i style="width:${progress(c)/c.missions.length*100}%"></i></div></div></button>`).join('')}</div></section>
<section class="gentle-note"><div>${art('fox')}</div><div>${label('A LITTLE, EVERY DAY')}<h2>不用一次学会。<br>今天弄懂一点点，就很好。</h2><p>答错了，阿栗会陪你找原因。难题会放进复习背包，<br>等你准备好了，再一起试一次。</p>${btn('打开我的复习背包 →','review','','text-button')}</div><span class="note-number">01—19<br><small>整本书的冒险<br>会在这里慢慢展开</small></span></section>${!saveAvailable?'<p class="notice">当前浏览器无法恢复本地记录。建议在学习设置中导出进度。</p>':''}`);}
function chapterPage(id){const c=chapterById(id);if(!c){go('home');return;}view='chapter';currentChapter=c;state.last=c.id;persist();lessonIndex=Math.min(lessonIndex,c.lessons.length-1);const l=c.lessons[lessonIndex];render(`<div class="page-top">${btn('← 小岛地图','home','','back')}<span>${c.book}</span></div><section class="chapter-heading">${label(c.id==='t1'?'TIME TRAVEL · SAMPLE':chapterTag(c))}<h1>${c.title}</h1><p>${c.brief}</p></section>${renderQuestTrail(c,state.done,esc)}<section class="lesson-panel ${c.theme}"><div class="lesson-picture">${art(l.visual)}<span class="lesson-stamp">先看一看 · 再听一听</span></div><div class="lesson-copy"><div class="lesson-counter">小故事 ${lessonIndex+1} / ${c.lessons.length}<div class="lesson-dots">${c.lessons.map((_,i)=>`<button aria-label="第 ${i+1} 个小故事" aria-pressed="${i===lessonIndex}" data-action="lesson" data-index="${i}" class="${i===lessonIndex?'selected':''}"></button>`).join('')}</div></div><h2>${l.title}</h2><p>${l.body}</p><div class="example"><p lang="en">${esc(l.example)}</p><small>${l.zh}</small><div>${btn('♫ 听英文','speak',`data-text="${esc(l.example)}"`,'sound-button')}${btn('听中文说明','speak',`data-lang="zh-CN" data-text="${esc(l.body)}"`,'sound-button')}</div></div>${renderLessonDemo(l,null,art,esc)}<div class="tags">${l.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="lesson-controls">${btn('← 上一个','lesson',`data-index="${Math.max(0,lessonIndex-1)}" ${lessonIndex===0?'disabled':''}`,'text-button')}${lessonIndex<c.lessons.length-1?btn('下一个小故事 →','lesson',`data-index="${lessonIndex+1}"`,'text-button'):btn('我来试一试 ↓','scroll-missions','','text-button')}</div></div></section><section id="missions"><div class="section-heading"><div>${label('PLAY, NOTICE, UNDERSTAND')}<h2>轮到你动手啦</h2></div><p>可以重玩 · 不计时 · 答错也没关系</p></div><div class="mission-grid">${c.missions.map((m,i)=>`<button class="mission-card ${state.done.includes(m.id)?'finished':''}" data-action="play" data-id="${m.id}"><span class="mission-number">${state.done.includes(m.id)?'✓':String(i+1).padStart(2,'0')}</span><div><h3>${m.title}</h3><p>${m.note}</p><small>${m.items.length} 个挑战 · ${state.done.includes(m.id)?'已完成，可重玩':'随时出发'}</small></div><span>↗</span></button>`).join('')}</div></section><p class="source-note">学习依据：${c.book}。例句、场景与练习为原创改编。${c.id==='t1'?'样板仅覆盖习惯、此刻进行和过去事件，完整时态摄影机关卡已在第 7 章开放。':'先掌握入门模型，后续章节会补充更丰富的结构与用法。'}</p>`);}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;}
function startPlay(id,review=false){const m=missionById(id);if(!review&&!m)return;stopSpeech();const questions=review?state.wrong.map(qById).filter(Boolean):m.items;if(!questions.length){go('review');return;}session={id,review,questions:[...questions],index:0,attempts:0,correct:0,first:0,answered:false,selected:[],pool:[],feedback:null,timeView:'habit',start:Date.now()};prepareQuestion();game();}
function prepareQuestion(){session.attempts=0;session.answered=false;session.selected=[];session.feedback=null;const q=session.questions[session.index];session.pool=q.type==='build'?shuffle(q.words.map((word,i)=>({word,i}))):shuffle(q.options||q.parts||[]);if(q.type==='build'&&session.pool.every((x,i)=>x.i===i))session.pool.reverse();session.timeView='habit';session.lab=newLabState();}
function highlighted(q){const s=esc(q.sentence);if(!q.target||q.target==='整句'||q.target==='主干'||q.target==='基本句型'||q.target==='省略的主语')return s;const t=esc(q.target);const i=s.indexOf(t);return i>=0?s.slice(0,i)+'<mark>'+t+'</mark>'+s.slice(i+t.length):s;}
function timeScene(which){const info={habit:['每天的习惯','反复出现的足迹，不表示此刻一定在做。','I water the flowers every day.'],now:['此刻正在发生','镜头里的动作正在进行。','I am watering the flowers now.'],past:['过去已经发生','昨天的照片，留在现在之前。','I watered the flowers yesterday.']}[which];return `<div class="time-view ${which}"><div class="timeline-scene">${art('flower')}<div class="water-drops"><i></i><i></i><i></i></div>${which==='habit'?'<div class="habit-dots"><i></i><i></i><i></i><i></i><i></i></div>':''}${which==='past'?'<span class="photo-label">YESTERDAY · 昨天的照片</span>':''}${which==='now'?'<span class="live-label">● NOW · 正在发生</span>':''}</div><strong>${info[0]}</strong><p>${info[1]}</p><p class="mini-en" lang="en">${info[2]}</p></div>`;}
function game(keepPosition=false){view=session.review?'review':'play';const q=session.questions[session.index],c=chapterById(q.chapter),m=missionById(q.mission);let interaction='';
if(CUSTOM_TYPES.has(q.type))interaction=renderPlayground(q,session,art,esc);
else if(q.type==='build')interaction=`<div class="build-scene"><div class="building-roof">${esc(q.pattern)}<span>把词块放入骨架</span></div><div class="building-slots">${q.words.map((_,i)=>{const item=session.selected[i];return `<div class="build-column"><span>${q.roles[i]||'词块'}</span><button data-action="unbuild" data-index="${i}" ${session.answered||!item?'disabled':''} aria-label="${item?'撤回 '+esc(item.word):'待放入词块 '+(i+1)}">${item?esc(item.word):'<span class="slot-plus">＋</span>'}</button></div>`;}).join('')}</div><div class="word-bank">${session.pool.map(item=>`<button data-action="build" data-index="${item.i}" ${session.answered||session.selected.some(x=>x.i===item.i)?'disabled':''}>${esc(item.word)}</button>`).join('')}</div>${btn('检查我的句子 ✓','check-build',session.selected.length!==q.words.length||session.answered?'disabled':'','primary')} ${btn('重新摆放','clear-build',session.answered?'disabled':'','text-button')}</div>`;
else if(q.type==='role')interaction=`<div class="train-platform"><span class="engine">▰<small>句子小火车</small></span>${q.parts.map((p,i)=>`<button class="carriage car-${i%4}" data-action="answer" data-answer="${esc(p)}" ${session.answered?'disabled':''}><span>${esc(p)}</span><i></i><i></i></button>`).join('')}</div><p class="interaction-tip">点击你找到的词块车厢 ↑</p>`;
else interaction=`${q.type==='time'?`<div class="time-lab"><div class="time-tabs" role="group" aria-label="观察时间镜头"><span>先玩一玩镜头</span>${['habit','now','past'].map((v,i)=>`<button data-action="time" data-value="${v}" aria-pressed="${session.timeView===v}" class="${session.timeView===v?'selected':''}">${['每天 ↻','此刻 ●','昨天 ◷'][i]}</button>`).join('')}</div><div id="time-observation">${timeScene(session.timeView)}</div></div>`:''}<div class="answer-options ${q.options.length===4?'four':''}">${session.pool.map((opt,i)=>`<button class="answer-option ${q.options===undefined?'':q.options.length===4?'mailbox':''}" data-action="answer" data-answer="${esc(opt)}" ${session.answered?'disabled':''}><span class="option-key">${String.fromCharCode(65+i)}</span><span>${esc(opt)}</span><span class="option-select">↗</span></button>`).join('')}</div>`;
render(`<div class="game-top">${btn('← '+(session.review?'复习背包':c.title),'leave-play',`data-id="${c.id}"`,'back')}<span>${session.review?'复习挑战':m.title}</span><span>${session.index+1} / ${session.questions.length}</span></div><div class="game-progress"><i style="width:${session.index/session.questions.length*100}%"></i></div><section class="play-header">${label(session.review?'LET’S TRY AGAIN':c.mechanic)}<h1>${gameTitle(q,c)}</h1><p>${CUSTOM_TYPES.has(q.type)?esc(q.zh):q.type==='build'?'按中文意思拼句。词块已经准备好了。':q.type==='role'?esc(q.zh):q.target==='整句'?'读一读场景，选择符合本题意思的表达或解释。':q.target==='主干'?'拿掉这句中可选的细节，保留主干。':'观察场景和高亮提示，慢慢想一想。'}</p></section><div class="game-layout chapter-${c.id} ${q.type==='time'?'time-game':''}"><aside class="question-scene ${c.theme}">${art(q.icon)}<div class="guide-caption">${q.type==='build'?'词块建筑台':q.type==='role'?'每节车厢，都有自己的工作':q.type==='time'?'故事没变，时间镜头变了':'先想意思，再找它的工作'}</div></aside><section class="challenge"><div class="sentence-box"><div class="sentence-label"><span>${q.type==='build'?'你的任务':'看看这句话'}</span>${btn('♫ 听英文','speak',`data-text="${esc(questionSentence(q))}"`,'sound-button')}</div>${q.type==='build'?`<h2>${esc(q.zh)}</h2>`:`<h2 lang="en">${CUSTOM_TYPES.has(q.type)?esc(questionSentence(q)):highlighted(q)}</h2><p>${q.type==='role'?esc(''):esc(q.zh)}</p>`}${q.type!=='build'&&q.target&&q.target!=='整句'?`<span class="target-label">${q.type==='role'?'':esc(q.target)}</span>`:''}</div>${interaction}<div id="feedback" aria-live="polite"></div><div class="game-tools">${btn('☀ 阿栗的提示','hint','','text-button')}${btn('听中文任务','speak',`data-lang="zh-CN" data-text="${esc(q.zh)}"`,'text-button')}<span>书内 ${esc(q.pages)} 页 · 原创练习</span></div></section></div>`,!keepPosition);
if(keepPosition){const next=document.querySelector('.word-bank button:not(:disabled)')||document.querySelector('[data-action="check-build"]');next?.focus({preventScroll:true});}if(session.feedback)showFeedback();if(state.settings.auto&&!keepPosition&&session.attempts===0)speak(questionSentence(q));}
function relatedStories(q){return q.links?.length?'<div class="related-stories"><p>回看相关小故事，关闭后继续当前挑战。</p>'+q.links.map(id=>btn(esc(chapterById(id).title),'related-story','data-id="'+id+'"','text-button')).join('')+'</div>':'';}
function showFeedback(){const f=session.feedback,q=session.questions[session.index];$('#feedback').innerHTML=`<div class="feedback ${f.correct?'correct':'retry'}"><span class="feedback-icon">${f.correct?'✦':'☀'}</span><div><h3>${f.correct?(session.attempts===1?'你发现规律啦！':'这次连接上啦！'):'没关系，我们一起看看'}</h3><p>${esc(q.why)}</p>${f.correct?`<p class="correct-answer" lang="en">${esc(q.sentence.replace('___',q.answer||''))}</p>${btn('♫ 听完整表达','speak',`data-text="${esc(q.sentence.replace('___',q.answer||''))}"`,'sound-button')}`:''}${btn(f.correct?(session.index===session.questions.length-1?'完成这次探险 →':'下一个挑战 →'):'明白了，再试一次',f.correct?'next':'retry','','primary')}${relatedStories(q)}</div></div>`;$('#feedback [data-action="next"],#feedback [data-action="retry"]')?.focus({preventScroll:true});$('#feedback').scrollIntoView({behavior:state.settings.motion?'smooth':'instant',block:'nearest'});}
function evaluate(answer){if(!session||session.answered||session.feedback)return;const q=session.questions[session.index];session.attempts++;const correct=q.type==='build'?answer===q.words.join('|'):answer===q.answer;if(correct){session.answered=true;session.correct++;if(session.attempts===1)session.first++;const old=state.solved[q.id];state.solved[q.id]={independent:!!old?.independent||session.attempts===1};if(session.review)state.wrong=state.wrong.filter(id=>id!==q.id);persist();document.querySelectorAll('[data-action="answer"],[data-action="build"],[data-action="unbuild"],[data-action="check-build"],[data-action="clear-build"]').forEach(b=>b.disabled=true);$('.question-scene')?.classList.add('celebrate');}else{if(!state.wrong.includes(q.id))state.wrong.push(q.id);persist();}document.querySelectorAll('[data-action="answer"],[data-action="build"],[data-action="unbuild"],[data-action="check-build"],[data-action="clear-build"]').forEach(b=>{b.disabled=true;if(correct&&b.dataset.answer===answer)b.classList.add('delivered');});session.feedback={correct};if(CUSTOM_TYPES.has(q.type))updateLab();showFeedback();}
function finish(){stopSpeech();if(!session.review&&!state.done.includes(session.id))state.done.push(session.id);persist();const c=chapterById(session.questions[0].chapter),m=missionById(session.id),next=c.missions[c.missions.findIndex(x=>x.id===session.id)+1];view='finish';render(`<section class="finish-screen"><div class="finish-stars">✧ <span>✦</span> ✧</div>${art('fox')} ${label('ONE LITTLE STEP, WELL DONE!')}<h1>${session.review?'背包又轻了一点！':'一小段冒险，完成啦！'}</h1><p>${session.review?'你重新想了一遍，也让知识更牢了一点。':'你不只选出了答案，也看见了句子背后的关系。'}</p><div class="finish-stats"><div><strong>${session.correct}</strong><span>完成挑战</span></div><div><strong>${session.first}</strong><span>本次独立完成</span></div><div><strong>${state.wrong.length}</strong><span>留待复习</span></div></div><p class="finish-note">${session.first===session.questions.length?'每一道都独立完成，真好。':'看过解释再做对，也是一种进步。答错的题已放进复习背包。'}</p><div class="finish-actions">${next&&!session.review?btn('下一个任务 →','play',`data-id="${next.id}"`):btn(session.review?'回到复习背包':'回到章节故事',''+(session.review?'review':'chapter'),`data-id="${c.id}"`)}${btn('回小岛地图','home','','secondary')}</div></section>`);}
function reviewPage(){view='review';render(`<div class="page-top">${btn('← 小岛地图','home','','back')}<span>温柔地，再试一次</span></div><section class="review-hero"><div>${label('YOUR LITTLE LEARNING BACKPACK')}<h1>复习背包</h1><p>有些知识，需要多见几次面。<br>答对后，它就会从背包里毕业。</p><div class="review-actions">${btn(state.wrong.length?`复习这 ${state.wrong.length} 个挑战 →`:'去小岛上探索 →',state.wrong.length?'start-review':'home')}</div></div>${art(state.wrong.length?'book':'fox')}</section>${state.wrong.length?`<div class="review-list">${state.wrong.map(id=>{const q=qById(id);return `<article><span>☀</span><div><small>${chapterById(q.chapter).title} · ${missionById(q.mission).title}</small><p lang="en">${esc(q.sentence)}</p></div>${btn('♫','speak',`data-text="${esc(q.sentence)}" aria-label="朗读 ${esc(q.sentence)}"`,'sound-button')}</article>`;}).join('')}</div>`:'<div class="empty-state"><span>✧</span><h2>背包现在空空的</h2><p>不用专门答错来填满它。学到的每一点，都算数。</p></div>'}`);}
function planPage(){view='plan';render(`<div class="page-top">${btn('← 小岛地图','home','','back')}<span>19 章 + 3 个拓展 · 全书精做路线</span></div><section class="chapter-heading">${label('A WHOLE WORLD TO DISCOVER')}<h1>一整本书，一座小世界。</h1><p>每章有自己的玩法，让抽象的语法变成可以看见、可以操作的故事。<br>19 章与三个附加专题均已开放，并可进入开园庆典练习跨章运用。</p></section><div class="plan-legend"><span><i class="dot"></i> 第 1–19 章与 be / used / it 已开放</span><span>◐ 原时态样板保留</span><span>✦ 跨章庆典 · 8 幕综合冒险</span></div><section class="roadmap">${roadmap.map((r,i)=>`<${r[5]?'button':'article'} class="roadmap-card ${r[5]?'available':''}" ${r[5]?`data-action="chapter" data-id="${r[5]}"`:''}><span class="road-number">${r[0]}</span><div class="road-art">${art(r[3])}</div><div><span class="status-badge">${r[5]?(r[5]==='t1'?'样板可玩':'已开放 · 可玩'):'后续计划'}</span><h2>${r[1]}</h2><p>${r[2]}</p><small>${r[4]}</small></div>${r[5]?'<span class="road-go">↗</span>':''}</${r[5]?'button':'article'}>`).join('')}</section><section class="plan-note"><h2>全书已经连起来，继续玩出理解</h2><p>每章已有图解故事、核心机制、观察动画与练习。当前开放第 1–19 章、三个附加专题、原时态样板和跨章庆典。本轮精修已覆盖全书；可以重玩、回看和复习，不必赶进度。</p><p>已完成软件检查不等于已经证明教学效果。后续会结合真实使用反馈，继续调整难度与表达。</p></section>`);}
function stopSpeech(){speechToken++;if('speechSynthesis'in window)window.speechSynthesis.cancel();}
function loadVoices(){if('speechSynthesis'in window)voices=window.speechSynthesis.getVoices();}
if('speechSynthesis'in window){loadVoices();window.speechSynthesis.addEventListener('voiceschanged',loadVoices);}
function speak(text,lang='en-US',rate=state.settings.rate){if(!('speechSynthesis'in window)){toast('这个浏览器没有朗读功能，文字仍可正常学习。');return;}stopSpeech();loadVoices();const utterance=new SpeechSynthesisUtterance(text.replace(/___/g,'blank'));utterance.lang=lang;utterance.rate=rate;const voice=voices.find(v=>v.lang.toLowerCase().startsWith(lang.slice(0,2)));if(voice)utterance.voice=voice;const token=speechToken;let began=false;utterance.onstart=()=>{began=true;toast(lang.startsWith('en')?'正在朗读英文 ♪':'正在朗读中文 ♪');};utterance.onerror=()=>{if(token===speechToken)toast('朗读未能播放。请检查设备声音或切换浏览器重试。');};utterance.onend=()=>{if(token===speechToken)toast('朗读完成，可以再听一次。');};window.speechSynthesis.speak(utterance);setTimeout(()=>{if(!began&&token===speechToken)toast('设备暂未开始朗读。请检查是否安装了对应语言的语音。');},5000);}
function dialog(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal();}
function settings(){loadVoices();dialog(`<div class="dialog-heading"><h2>按你的节奏来</h2>${btn('×','close','','close')}</div><p>不用快，听清楚、看明白就好。</p><label class="field">朗读速度<select id="rate"><option value=".65" ${state.settings.rate===.65?'selected':''}>慢一点 · 0.65 倍</option><option value=".8" ${state.settings.rate===.8?'selected':''}>轻松听 · 0.8 倍</option><option value="1" ${state.settings.rate===1?'selected':''}>正常速度 · 1 倍</option></select></label><label class="toggle-row"><span><strong>自动读英文题目</strong><small>进入新题时朗读；也可以随时手动重听。</small></span><input type="checkbox" id="auto-read" ${state.settings.auto?'checked':''}></label><label class="toggle-row"><span><strong>开启场景动画</strong><small>关闭后画面静止，操作仍可正常进行。</small></span><input type="checkbox" id="motion" ${state.settings.motion?'checked':''}></label><p class="settings-help">朗读使用浏览器或系统语音，不录音、不开麦。声音与离线可用性取决于设备。${voices.some(v=>v.lang.startsWith('en'))?'已检测到英文声音。':'尚未检测到英文声音，首次播放时系统可能继续加载。'}</p><div class="settings-actions">${btn('♫ 试听英文','test-speech','','secondary')}${btn('导出进度','export','','secondary')}<label class="file-button">恢复进度<input type="file" id="import-progress" accept="application/json,.json"></label></div><p class="settings-help">进度仅保存在当前浏览器。换设备前可导出，恢复时会覆盖当前进度。</p>${btn('保存设置','save-settings','','primary wide')}`);}
function about(){dialog(`<div class="dialog-heading"><h2>学习说明</h2>${btn('×','close','','close')}</div><p>语法小岛把抽象规则变成有意义的操作。建议先看每章小故事，再做任务；如果还不认识英文，请使用英文朗读和中文提示，儿童可由成人陪同。</p><p>当前开放第 1–19 章与 be、used、it 三个拓展的核心学习目标，含 ${allQuestions.length} 个原创挑战。第 7 章新增十二种常见时态组合，原入门样板仍可重玩。三个附加专题已开放，第 1–6 章已完成本轮精修；第 1–19 章已完成本轮精修，跨章综合庆典已开放；可继续重玩迁移。</p><p>采用《一看就懂的英语语法书》的章节路线，例句、场景与练习为原创改编；使用语境限定和例外提示，避免机械套用简化口诀。五种句型是入门框架。</p><p>补充核对：<a href="https://dictionary.cambridge.org/grammar/british-grammar/complements" target="_blank" rel="noopener">Cambridge · Complements</a>；<a href="https://dictionary.cambridge.org/uk/grammar/british-grammar/verb-patterns-with-and-without-objects" target="_blank" rel="noopener">Verb patterns</a>；<a href="https://learnenglishkids.britishcouncil.org/grammar-vocabulary/grammar-practice/present-simple-present-continuous" target="_blank" rel="noopener">British Council · 现在时入门</a>。</p><p>没有倒计时。答错不扣命：查看解释后重试，并在复习背包重新作答。完成任务与首次答对会分别记录。</p>${btn('明白了，一起探索','close','','primary')}`);}
function download(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='语法小岛-学习进度.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('学习进度已导出。');}
let importState=null;
document.addEventListener('change',async e=>{if(e.target.id!=='import-progress')return;try{const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error('文件太大');importState=sanitize(JSON.parse(await file.text()));$('#dialog-content').innerHTML=`<h2>恢复这份进度？</h2><p>备份包含 ${importState.done.length} 个已完成任务、${Object.keys(importState.solved).length} 个已学挑战。恢复会覆盖当前浏览器记录。</p><div class="settings-actions">${btn('确认恢复','confirm-import')}${btn('保留当前进度','settings','','secondary')}</div>`;}catch{toast('无法读取这份进度，请选择语法小岛导出的 JSON 文件。');e.target.value='';}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;switch(a){
case'home':go('home');break;case'chapter':lessonIndex=0;go('chapter/'+b.dataset.id);break;case'review':go('review');break;case'plan':go('plan');break;case'scroll-map':$('#islands')?.scrollIntoView({behavior:state.settings.motion?'smooth':'instant'});break;case'scroll-missions':$('#missions')?.scrollIntoView({behavior:state.settings.motion?'smooth':'instant'});break;
case'lesson':lessonIndex=Number(b.dataset.index);stopSpeech();chapterPage(currentChapter.id);break;case'play':go('play/'+b.dataset.id);break;case'start-review':go('practice');break;case'leave-play':go(session?.review?'review':'chapter/'+b.dataset.id);break;
case'answer':evaluate(b.dataset.answer);break;
case'lab-bin':if(session?.feedback)return;session.lab.bin=b.dataset.value;updateLab();break;
case'lab-count':if(session?.feedback)return;session.lab.count=Math.max(1,Math.min(5,session.lab.count+Number(b.dataset.value)));updateLab();break;
case'lab-clue':{if(session?.feedback)return;const i=Number(b.dataset.index);session.lab.clues=session.lab.clues.includes(i)?session.lab.clues.filter(v=>v!==i):[...session.lab.clues,i];updateLab();break;}
case'lab-person':if(session?.feedback)return;session.lab.subject=b.dataset.value;updateLab();break;
case'lab-time':if(session?.feedback)return;session.lab.time=b.dataset.value;updateLab();break;
case'lab-be':if(session?.feedback)return;session.lab.be=b.dataset.value;updateLab();break;
case'demo-motion':{const frame=$('#lesson-demo .observation-frame');if(frame){const paused=frame.classList.toggle('paused');b.setAttribute('aria-pressed',String(!paused));b.textContent=paused?'▶ 播放示意':'❚❚ 暂停示意';if(!state.settings.motion)toast('当前已关闭场景动画；文字和观察切换仍可使用。');}break;}
case'related-story':{const c=chapterById(b.dataset.id),l=c?.lessons[0];if(l)dialog('<div class="dialog-heading"><h2>'+esc(c.title)+'</h2>'+btn('×','close','','close')+'</div><p>'+esc(l.body)+'</p><div class="example"><p lang="en">'+esc(l.example)+'</p><small>'+esc(l.zh)+'</small></div>'+btn('♫ 听例句','speak','data-text="'+esc(l.example)+'"','sound-button')+btn('关闭，继续当前挑战','close','','primary'));break;}
case'lesson-demo':{const l=currentChapter?.lessons[lessonIndex],host=$('#lesson-demo');if(host&&l?.demo){host.outerHTML=renderLessonDemo(l,b.dataset.value,art,esc);document.querySelector('#lesson-demo [data-value="'+b.dataset.value+'"]')?.focus({preventScroll:true});}break;}
case'lab-direct':if(session?.feedback)return;session.lab.settings[b.dataset.axis]=b.dataset.value;updateLab();break;
case'check-lab':evaluate(labAnswer(session.questions[session.index],session.lab));break;
case'build':if(session?.feedback)return;session.selected.push(session.pool.find(x=>x.i===Number(b.dataset.index)));game(true);break;
case'unbuild':if(session?.feedback)return;session.selected.splice(Number(b.dataset.index),1);game(true);break;
case'clear-build':if(session?.feedback)return;session.selected=[];game(true);break;
case'check-build':evaluate(session.selected.map(x=>x.word).join('|'));break;
case'retry':session.feedback=null;session.selected=[];session.lab=newLabState();game();break;
case'next':stopSpeech();if(session.index===session.questions.length-1)finish();else{session.index++;prepareQuestion();game();}break;
case'hint':{if(!session)return;session.attempts=Math.max(1,session.attempts);const q=session.questions[session.index];dialog(`<div class="dialog-heading"><h2>阿栗的小提示</h2>${btn('×','close','','close')}</div><div class="hint-art">${art('fox')}</div><p>${esc(q.why)}</p><p class="settings-help">看提示很正常。这一题会记作“看过提示完成”，继续试试吧。</p>${btn('我来试一试','close')}`);break;}
case'time':session.timeView=b.dataset.value;document.querySelectorAll('[data-action="time"]').forEach(t=>{t.classList.toggle('selected',t.dataset.value===session.timeView);t.setAttribute('aria-pressed',String(t.dataset.value===session.timeView));});$('#time-observation').innerHTML=timeScene(session.timeView);break;
case'speak':speak(b.dataset.text,b.dataset.lang||'en-US');break;case'settings':settings();break;case'about':about();break;case'close':$('#dialog').close();break;
case'test-speech':speak('Hello! Welcome to Grammar Island.','en-US',Number($('#rate').value));break;
case'save-settings':state.settings.rate=Number($('#rate').value);state.settings.auto=$('#auto-read').checked;state.settings.motion=$('#motion').checked;persist();$('#dialog').close();toast('已保存，按你的节奏来。');break;
case'export':download();break;case'confirm-import':if(importState){state=importState;importState=null;persist();$('#dialog').close();go('home');toast('进度恢复完成。');}break;
}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close();});
function route(){stopSpeech();const [path,id]=location.hash.slice(1).split('/');if(path==='play'){startPlay(id);return;}if(path==='practice'){startPlay(null,true);return;}session=null;if(path==='chapter')chapterPage(id);else if(path==='review')reviewPage();else if(path==='plan')planPage();else home();}
window.addEventListener('hashchange',route);window.addEventListener('pagehide',stopSpeech);route();
